// Journey check by code, no LLM: is the tracking gap normal, where was the car last, and can it still arrive in the promise window by road?
// @include travel.js
const i = $('Start').first().json;
const c = $json;
if (!c.found) return [{ json: { ok: false, error: c.error } }];
// Placeholder numbers from the Settings page (otr_settings): tracker silence, road speed, EU driving rules, on-time spare.
const S = c.settings, NORMAL_GAP_MIN = S.normal_gap_min, SPEED_KMH = S.road_speed_kmh, BUFFER_H = S.on_time_spare_h;
const BLOCK = S.break_after_min, BREAK = S.break_min, DAY = S.daily_drive_max_min, REST = S.daily_rest_min;
const s = c.snapshot, H = 36e5, M = 6e4;
const now = Date.parse(s.snapshot_now);
const win = (s.time_windows || []).find((w) => w.purpose === 'CUSTOMER_DELIVERY_PROMISE');
const pickup = (s.time_windows || []).find((w) => w.purpose === 'SELECTED_PICKUP_SLOT');
const last = (s.tracking_latest || []).slice(-1)[0];
const res = s.travel_reservations || [];

// 1) Tracking gap: normal or not.
const gapMin = last ? Math.round((now - Date.parse(last.observed_at)) / M) : null;
const ferryNow = res.find((r) => r.kind === 'FERRY' && Date.parse(r.departure_at) - 2 * H <= now && now <= Date.parse(r.expected_arrival_at));
const hotelNow = res.find((r) => r.kind === 'HOTEL' && Date.parse(r.check_in_at) <= now && now <= Date.parse(r.check_out_at));
const beforePickup = (pickup && now < Date.parse(pickup.start_at)) || ['NEW', 'WAITING_FOR_PICKUP'].includes(s.order.status);
let normal, why;
if (beforePickup) { normal = true; why = 'car not picked up yet (before the pickup slot), so no tracking is expected'; }
else if (ferryNow) { normal = true; why = `on the ferry ${ferryNow.route_label || ''} (${ferryNow.departure_at} -> ${ferryNow.expected_arrival_at}); tracking often drops at sea`; }
else if (hotelNow) { normal = true; why = `planned hotel stop in ${hotelNow.city} until ${hotelNow.check_out_at}`; }
else if (gapMin === null) { normal = false; why = 'car should be moving but there is no tracking at all'; }
else if (gapMin <= NORMAL_GAP_MIN) { normal = true; why = `last update ${gapMin} min ago (up to ${NORMAL_GAP_MIN} min is normal)`; }
else { normal = false; why = `no update for ${Math.floor(gapMin / 60)} h ${gapMin % 60} min, with no ferry or planned stop to explain it`; }

// Car stopped: the last two positions, at least 30 min apart, show under 1 km of progress (the dataset has no speed).
const prev = (s.tracking_latest || []).slice(-2)[0];
const stopped = Boolean(prev && last && prev !== last && Date.parse(last.observed_at) - Date.parse(prev.observed_at) >= 30 * M && Math.abs(prev.distance_remaining_km - last.distance_remaining_km) < 1);

// 2) Last known position.
const pos = last ? nearestCity(s.pickup?.city, s.delivery?.city, last.progress_fraction) : null;

// 3) Road arrival: km left at road speed, a break after each driving block, daily rest after the daily driving limit (EU rules).
// drive_used_min: minutes already worked today (a replacement driver's train or flight there); else fresh hours (the dataset does not say).
// No tracking yet (car not picked up): the order's planned route gives the distance (legs not yet completed).
const planKm = (s.route_plan?.legs || []).filter((l) => l.status !== 'COMPLETED').reduce((t, l) => t + (Number(l.distance_km) || 0), 0) || null;
const km = i.km_left !== '' && i.km_left != null && !Number.isNaN(Number(i.km_left)) ? Number(i.km_left) : last?.distance_remaining_km ?? planKm;
const kmFrom = i.km_left !== '' && i.km_left != null ? 'driver' : last?.distance_remaining_km != null ? 'tracking' : planKm ? 'route plan' : '';
const from = i.from_time ? Date.parse(i.from_time) : now;
const ferryAhead = res.find((r) => r.kind === 'FERRY' && Date.parse(r.departure_at) > now);
let road = null, eta = null, basis;
if (ferryAhead || ferryNow) {
  eta = last?.estimated_delivery_at ? Date.parse(last.estimated_delivery_at) : null;
  basis = 'a ferry leg is part of the trip, so the tracking ETA is used; for ferry timing call plan_rebooking';
} else if (km != null && !Number.isNaN(from)) {
  let t = from, left = km / SPEED_KMH * 60, day = Math.min(DAY, Number(i.drive_used_min) || 0), block = 0, breaks = 0, rest = 0;
  while (left > 0) {
    const step = Math.min(left, BLOCK - block, DAY - day);
    t += step * M; left -= step; block += step; day += step;
    if (left <= 0) break;
    if (day >= DAY) { t += REST * M; rest += REST; day = 0; block = 0; } else if (block >= BLOCK) { t += BREAK * M; breaks += BREAK; block = 0; }
  }
  eta = t;
  road = { km_left: km, drive_hours: +(km / SPEED_KMH).toFixed(1), break_hours: +(breaks / 60).toFixed(2), rest_hours: rest / 60, from: isoMin(from) };
  basis = `${km} km (from ${kmFrom}) at ${SPEED_KMH} km/h + EU breaks and rest, from ${i.from_time ? 'the given restart time' : 'now'}`;
  // The driver app's own ETA may know about traffic or a stop we cannot see; the slower estimate wins (not for a restart time).
  const appEta = !i.from_time && last?.estimated_delivery_at ? Date.parse(last.estimated_delivery_at) : null;
  if (appEta > eta) { basis += `; the driver app ETA ${isoMin(appEta)} is later, so it is used`; eta = appEta; }
} else basis = 'no km left in tracking or route plan: ask the driver for position';

let verdict = 'unknown', bufferH = null, lateH = null, suggested = null;
if (eta && win) {
  const end = Date.parse(win.end_at), start = Date.parse(win.start_at);
  bufferH = +((end - eta) / H).toFixed(1);
  lateH = +Math.max(0, (eta - end) / H).toFixed(1);
  verdict = bufferH >= BUFFER_H ? 'on_time' : bufferH >= 0 ? 'at_risk' : 'late';
  if (verdict === 'late') { // new window: same length as the old one (min 2 h), starting at the next full hour after arrival
    const len = Math.max(2 * H, end - start), st = Math.ceil(eta / H) * H;
    suggested = { start_at: isoMin(st), end_at: isoMin(st + len) };
  }
}
return [{ json: { ok: true, order_ref: c.order_ref, now: s.snapshot_now,
  tracking: { last_observed_at: last?.observed_at || null, gap_minutes: gapMin, normal, why, stopped, km_left: last?.distance_remaining_km ?? null, progress: last?.progress_fraction ?? null, dataset_eta: last?.estimated_delivery_at || null, location_quality: last?.location_quality || null },
  last_known_position: pos ? { near_city: pos.city, lat: pos.lat, lon: pos.lon, observed_at: last.observed_at, basis: `straight line ${s.pickup?.city} -> ${s.delivery?.city} at ${Math.round(last.progress_fraction * 100)}% progress, nearest city (estimate)` } : null,
  road, eta: eta ? isoMin(eta) : null, eta_basis: basis,
  promise_window: win ? `${win.start_at} -> ${win.end_at}` : null,
  verdict, buffer_hours: bufferH, late_hours: lateH, suggested_new_window: suggested,
  rule: `on_time = at least ${BUFFER_H} h before the window ends; at_risk = before the end but less slack; late = after the end` } }];
